export type SlideData = {
  name: string;
  alt: string;
  width: number;
  height: number;
  widths: number[];
  blur: string | null;
};

/**
 * Responsive slide image generated by scripts/optimize-images.mjs.
 * Plain <img> because the static export disables next/image srcset.
 */
export default function Slide({ slide, priority = false }: { slide: SlideData; priority?: boolean }) {
  const url = (w: number) => `/slides/${slide.name}-${w}.webp`;

  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={url(slide.width)}
      srcSet={slide.widths.map((w) => `${url(w)} ${w}w`).join(", ")}
      sizes={`(min-width: ${slide.width}px) ${slide.width}px, 100vw`}
      width={slide.width}
      height={slide.height}
      alt={slide.alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding="async"
      data-hero={priority || undefined}
      className="w-fit h-auto"
      style={
        slide.blur
          ? { backgroundImage: `url(${slide.blur})`, backgroundSize: "cover" }
          : undefined
      }
    />
  );
}
